/**
 * The card that asks the visitor whether a world may use a capability
 * (VEML 4.0 §9): the world's origin and title, a row per capability with
 * Allow and Block, and a line saying the answer is remembered.
 *
 * Fetched the first time a world asks (feedbackSurface.ts), so a world that
 * asks for nothing pays nothing for it. The surface keeps the question and
 * its answers; this only draws the card and reports each press.
 */
import { describeCapability, type ConsentAnswer, type ConsentRequest } from '../capabilities/consent';

/**
 * The card for `req`, not yet on the page. `answered` is called with each
 * row's capability, the answer pressed, and the row, which the surface takes
 * down.
 */
export function buildConsentCard(
  doc: Document,
  req: ConsentRequest,
  answered: (capability: string, answer: ConsentAnswer, row: HTMLElement) => void,
): HTMLElement {
  const el = (tag: string, attrs?: Record<string, string>, text?: string): HTMLElement => {
    const node = doc.createElement(tag);
    if (attrs) for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, v);
    if (text !== undefined) node.textContent = text;
    return node;
  };
  const card = el('div', {
    'data-webverse-consent': '',
    role: 'dialog',
    'aria-label': 'This world asks for permission',
  });
  card.style.cssText =
    'position:fixed;left:50%;bottom:24px;transform:translateX(-50%);z-index:12;' +
    'width:min(440px,92vw);box-sizing:border-box;padding:14px 16px;border-radius:8px;' +
    'background:var(--webverse-feedback-bg,#101014);color:var(--webverse-feedback-fg,#dfe3ea);' +
    'border:1px solid rgba(223,227,234,0.35);font:14px/1.45 system-ui,sans-serif;text-align:left;' +
    'box-shadow:0 8px 30px rgba(0,0,0,0.5);pointer-events:auto;';
  const heading = el('p');
  heading.style.cssText = 'margin:0 0 10px;';
  const origin = el('strong', { 'data-webverse-consent-origin': '' }, req.origin);
  heading.append(origin, doc.createTextNode(req.title ? ` (${req.title}) asks to:` : ' asks to:'));
  card.appendChild(heading);
  const list = el('div');
  list.style.cssText = 'display:flex;flex-direction:column;gap:8px;';
  for (const cap of req.capabilities) {
    const row = el('div', { 'data-webverse-consent-row': cap });
    row.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:10px;';
    row.appendChild(el('span', undefined, describeCapability(cap)));
    const buttons = el('span');
    buttons.style.cssText = 'display:flex;gap:6px;flex:none;';
    const button = (attr: string, text: string, answer: ConsentAnswer): HTMLElement => {
      const b = el('button', { type: 'button', [attr]: '' }, text);
      b.style.cssText =
        'font:inherit;color:inherit;background:transparent;border:1px solid currentColor;' +
        'border-radius:4px;padding:2px 10px;cursor:pointer;pointer-events:auto;';
      b.addEventListener('click', () => answered(cap, answer, row));
      return b;
    };
    buttons.append(button('data-webverse-consent-allow', 'Allow', 'granted'), button('data-webverse-consent-block', 'Block', 'denied'));
    row.appendChild(buttons);
    list.appendChild(row);
  }
  card.appendChild(list);
  const note = el('p', undefined, 'Your answer is remembered for this site; the menu can forget it.');
  note.style.cssText = 'margin:10px 0 0;font-size:12px;opacity:0.75;';
  card.appendChild(note);
  return card;
}
